package org.dextur.reputation.domain.policy;

import java.util.*;
import org.dextur.reputation.api.ReputationPolicyResult.Decision;
import org.dextur.reputation.api.RecoverySnapshot.Status;
import org.dextur.reputation.domain.protection.Fixed;

public record PolicyRules(Map<String,Definition> policies,Limits administration,boolean healthEnabled,boolean informationEnabled,String fingerprint) {
    public static final List<String> BUILT_INS=List.of("reputation.vote","chat.send","chat.cooldown","shop.use","auction.use","auction.create-listing","auction.listing-limit","warps.create","warps.limit","warps.visit","rewards.daily","rewards.weekly","kits.use","reward-codes.use","buyer.use","buyer.limit","support.create-ticket","support.open-ticket-limit","health.maximum","support.emergency-contact");
    public PolicyRules{policies=Collections.unmodifiableMap(new TreeMap<>(policies));Objects.requireNonNull(administration);Objects.requireNonNull(fingerprint);}
    public static void identifier(String id){if(id==null||!id.matches("[a-z][a-z0-9-]{0,47}(?:\\.[a-z][a-z0-9-]{0,47}){1,3}"))throw new IllegalArgumentException("Invalid policy ID");}
    public record Limits(long minimum,long maximum,long single,boolean requireReason){public Limits{if(minimum>0||maximum<0||minimum>=maximum||single<1)throw new IllegalArgumentException("Administration bounds");Fixed.units(minimum);Fixed.units(maximum);Fixed.units(single);}}
    public record Definition(String id,boolean enabled,Map<String,String> names,List<Rule> rules){public Definition{identifier(id);names=Map.copyOf(names);if(!names.keySet().containsAll(Set.of("ru_RU","en_US")))throw new IllegalArgumentException("Policy locales");rules=rules.stream().sorted(Comparator.comparingInt(Rule::priority)).toList();if(rules.isEmpty()||rules.size()>64)throw new IllegalArgumentException("Policy rule bounds");var priorities=new HashSet<Integer>();var conditions=new HashSet<Condition>();int defaults=0;for(var r:rules){if(!priorities.add(r.priority())||!conditions.add(r.condition()))throw new IllegalArgumentException("Ambiguous policy rules");if(r.condition().unconditional()){defaults++;if(r!=rules.getLast())throw new IllegalArgumentException("Default must have last priority");}}if(defaults!=1)throw new IllegalArgumentException("Exactly one default rule required");}}
    public record Condition(Long minimum,Long maximum,Set<String> tiers,Set<Status> recovery,Map<String,String> context){public Condition{tiers=Set.copyOf(tiers);recovery=Set.copyOf(recovery);context=Map.copyOf(context);if(minimum!=null&&maximum!=null&&minimum>maximum||context.size()>16)throw new IllegalArgumentException("Policy condition");for(var e:context.entrySet())if(!e.getKey().matches("[a-z][a-z0-9_.-]{0,63}")||e.getValue().length()>128)throw new IllegalArgumentException("Public context bounds");}public boolean unconditional(){return minimum==null&&maximum==null&&tiers.isEmpty()&&recovery.isEmpty()&&context.isEmpty();}}
    public record Rule(int priority,Condition condition,Decision decision,Long limit,long multiplierUnits,Long valueUnits){public Rule{Objects.requireNonNull(condition);Objects.requireNonNull(decision);if(decision==Decision.UNAVAILABLE||limit!=null&&limit<0||multiplierUnits<0||multiplierUnits>Fixed.units(1000)||valueUnits!=null&&(valueUnits<Fixed.units(2)||valueUnits>Fixed.units(40)))throw new IllegalArgumentException("Policy output bounds");}}
}
